import {readDoorAnimations,validateDoorAnimations,doorFramePixels,paintDoorPixel} from './door-animation.js';
export function nativeDoorWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc;
 function open(){try{
  const session=api.session?.();if(!session)throw Error('Open the original ROM first.');const hash=session.id,reader=session.reader,native=readDoorAnimations(reader,hash),draft=structuredClone(api.project().doorAnimations?.[hash]||{doors:{}});let id=0,frame=0,colour=1,dirty=false,down=false,last=null,previewTimer=null;
  api.modal('Native door frames',`<p>Edit the three animated opening frames used by native doors. Closing plays them in reverse; the closed frame comes from the map. Each style is shared by every map using that native door.</p><label>Door style<select id="nativeDoorStyle">${native.doors.map(d=>`<option value="${d.id}">${esc(d.name)} · metatile ${d.metatile.toString(16)}</option>`).join('')}</select></label><button id="nativeDoorAdd" type="button">＋ Duplicate as a new door style</button><div id="nativeDoorRegistration"></div><label>Palette preview map<select id="nativeDoorMap">${reader.maps.map(m=>`<option value="${esc(m.key)}" ${m.key===api.map()?.rom?.key?'selected':''}>${esc(m.label||m.name||m.key)}</option>`).join('')}</select></label><div class="studio-actions"><button id="nativeDoorPrev" type="button">Previous frame</button><button id="nativeDoorNext" type="button">Next frame</button><button id="nativeDoorPlay" type="button">▶ Preview</button><button id="nativeDoorCopy" type="button">Copy previous frame</button></div><p id="nativeDoorStatus" class="studio-status"></p><canvas id="nativeDoorCanvas" aria-label="Paint native door pixels" style="display:block;width:256px;max-width:100%;height:auto;image-rendering:pixelated;touch-action:none"></canvas><div class="studio-actions" id="nativeDoorColours"></div><label>Door sound<select id="nativeDoorSound"><option value="0">Normal</option><option value="1">Sliding</option></select></label><label><input id="nativeDoorTimingEnabled" type="checkbox" ${draft.timing!==undefined?'checked':''}> Change timing for all native doors</label><label>Ticks per frame<input id="nativeDoorTiming" type="number" min="1" max="30" value="${draft.timing||4}"></label><div class="studio-actions"><button id="nativeDoorReset" type="button">Restore this style</button><button id="nativeDoorPNG" type="button">Export frame PNG</button></div><p class="hint-line">Palette colours come from the preview map; painting saves colour indices. New styles register an unused metatile ID and keep the copied dimensions. Assign door behaviour and a warp to that metatile in your map. These edits affect native animated doors, including shared styles outside this project.</p>`,()=>{if(!dirty)return;validateDoorAnimations({[hash]:draft});api.change(()=>{api.project().doorAnimations??={};api.project().doorAnimations[hash]=structuredClone(draft);});api.toast('Native door frame edits saved. Export the edited ROM to use them.');},'Save door frames');
  const canvas=$('#nativeDoorCanvas');let door;const styles=()=>{$('#nativeDoorStyle').innerHTML=[...native.doors,...Object.entries(draft.doors).filter(([i])=>+i>=32).map(([i,d])=>({...d,id:+i}))].map(d=>`<option value="${d.id}" ${d.id===id?'selected':''}>${esc(d.name)} · metatile ${d.metatile.toString(16)}</option>`).join('');};styles();$('#nativeDoorAdd').onclick=()=>{const next=Array.from({length:64},(_,i)=>i+32).find(i=>!draft.doors[i]);if(next===undefined){api.error(Error('Up to 64 additional door styles.'));return;}const used=new Set([...native.doors,...Object.values(draft.doors)].map(d=>d.metatile)),metatile=Array.from({length:1024},(_,i)=>i).find(i=>!used.has(i));draft.doors[next]={name:'New door '+(next-31),metatile,size:door.size,sound:door.sound,palettes:[...door.palettes],tiles:[...door.tiles]};id=next;dirty=true;styles();load();};
  function store(){const old=native.doors[id];if(!old){draft.doors[id]=structuredClone(door);dirty=true;return;}if(door.sound===old.sound&&door.tiles.every((n,i)=>n===old.tiles[i]))delete draft.doors[id];else draft.doors[id]={size:door.size,sound:door.sound,tiles:[...door.tiles]};dirty=true;}
  function stop(){if(previewTimer)clearInterval(previewTimer);previewTimer=null;$('#nativeDoorPlay').textContent='▶ Preview';}
  function draw(){const map=reader.byKey($('#nativeDoorMap').value),a=reader.atlas(map),split=reader.profile(map).primaryPalettes,pixels=doorFramePixels(door,frame);canvas.width=16;canvas.height=door.size?32:16;const ctx=canvas.getContext('2d'),image=ctx.createImageData(16,canvas.height);for(let y=0;y<canvas.height;y++)for(let x=0;x<16;x++){const bank=door.palettes[Math.floor(y/8)*2+Math.floor(x/8)],source=bank<split?a.primary:a.secondary,n=pixels[y*16+x],c=reader.u16(source.palettes+(bank*16+n)*2);image.data.set([(c&31)*255/31,(c>>5&31)*255/31,(c>>10&31)*255/31,n?255:0],(y*16+x)*4);}ctx.putImageData(image,0,0);$('#nativeDoorStatus').textContent=`Frame ${frame+1} of 3 · 16 × ${canvas.height} pixels · colour ${colour} · shared style`;const bank=door.palettes[0],source=bank<split?a.primary:a.secondary;$('#nativeDoorColours').innerHTML=Array.from({length:16},(_,n)=>{const c=reader.u16(source.palettes+(bank*16+n)*2),rgb=`rgb(${(c&31)*255/31},${(c>>5&31)*255/31},${(c>>10&31)*255/31})`;return`<button type="button" data-door-colour="${n}" aria-label="Colour ${n}${n===0?' transparent':''}" aria-pressed="${n===colour}" style="background:${rgb};min-width:36px;flex:0 0 36px;border-width:${n===colour?3:1}px">${n}</button>`;}).join('');document.querySelectorAll('[data-door-colour]').forEach(b=>b.onclick=()=>{colour=+b.dataset.doorColour;draw();});}
  function load(){stop();door=structuredClone({...native.doors[id],...draft.doors[id]});const box=$('#nativeDoorRegistration');box.innerHTML=id>=32?`<label>Style name<input id="newDoorName" maxlength="80" value="${esc(door.name)}"></label><label>Metatile ID (decimal)<input id="newDoorMetatile" type="number" min="0" max="1023" value="${door.metatile}"></label><label>Eight palette indices, comma separated<input id="newDoorPalettes" value="${door.palettes.join(',')}"></label><button id="newDoorDelete" type="button">Remove new style</button>`:'';if(id>=32){$('#newDoorName').onchange=()=>{door.name=$('#newDoorName').value;store();};$('#newDoorMetatile').onchange=()=>{door.metatile=+$('#newDoorMetatile').value;store();};$('#newDoorPalettes').onchange=()=>{const values=$('#newDoorPalettes').value.split(',').map(Number);if(values.length!==8||values.some(n=>!Number.isInteger(n)||n<0||n>15)){api.error(Error('Enter eight palette indices from 0 to 15.'));return;}door.palettes=values;store();draw();};$('#newDoorDelete').onclick=()=>{delete draft.doors[id];dirty=true;id=0;styles();load();};}$('#nativeDoorSound').value=door.sound;frame=0;draw();}
  function paint(e){e.preventDefault();const rect=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-rect.left)*16/rect.width),y=Math.floor((e.clientY-rect.top)*canvas.height/rect.height);if(x<0||x>=16||y<0||y>=canvas.height)return;const from=last||{x,y},steps=Math.max(Math.abs(x-from.x),Math.abs(y-from.y),1);for(let i=0;i<=steps;i++)paintDoorPixel(door,frame,Math.round(from.x+(x-from.x)*i/steps),Math.round(from.y+(y-from.y)*i/steps),colour);last={x,y};store();draw();}
  canvas.onpointerdown=e=>{stop();down=true;last=null;canvas.setPointerCapture?.(e.pointerId);paint(e);};canvas.onpointermove=e=>{if(down)paint(e);};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=()=>{down=false;last=null;};
  $('#nativeDoorStyle').onchange=()=>{id=+$('#nativeDoorStyle').value;load();};$('#nativeDoorMap').onchange=draw;$('#nativeDoorPrev').onclick=()=>{stop();frame=(frame+2)%3;draw();};$('#nativeDoorNext').onclick=()=>{stop();frame=(frame+1)%3;draw();};$('#nativeDoorSound').onchange=()=>{door.sound=+$('#nativeDoorSound').value;store();};
  $('#nativeDoorPlay').onclick=()=>{if(previewTimer){stop();return;}$('#nativeDoorPlay').textContent='Stop preview';previewTimer=setInterval(()=>{if(!canvas.isConnected){clearInterval(previewTimer);previewTimer=null;return;}frame=(frame+1)%3;draw();},((draft.timing||4)+1)*1000/60);};
  $('#nativeDoorCopy').onclick=()=>{stop();const size=door.size?256:128,previous=(frame+2)%3;door.tiles.splice(frame*size,size,...door.tiles.slice(previous*size,(previous+1)*size));store();draw();};$('#nativeDoorReset').onclick=()=>{delete draft.doors[id];dirty=true;if(id>=32){id=0;styles();}load();};
  const timing=()=>{stop();if($('#nativeDoorTimingEnabled').checked)draft.timing=+$('#nativeDoorTiming').value;else delete draft.timing;dirty=true;};$('#nativeDoorTimingEnabled').onchange=timing;$('#nativeDoorTiming').onchange=timing;$('#nativeDoorPNG').onclick=()=>canvas.toBlob(blob=>api.save(blob,'Door_'+id+'_Frame_'+(frame+1)+'.png').catch(api.error),'image/png');load();
 }catch(e){api.error(e);}}
 return{open};
}
